    public static object sortedBy(object xs, object key)
    {
      var l = items(xs); var idx = new int[l.Count]; var k = new double[l.Count];
      for (int i = 0; i < l.Count; i++) { idx[i] = i; k[i] = num(invoke(key, l[i])); }
      System.Array.Sort(idx, (p, q) => k[p] != k[q] ? k[p].CompareTo(k[q]) : p.CompareTo(q));
      var o = new List<object>(l.Count); foreach (int i in idx) o.Add(l[i]); return o;
    }
    public static object summed(object xs) { double s = 0; foreach (var x in view(xs)) s += num(x); return s; }
    public static List<object> codepoints(object s) { var o = new List<object>(); string t = (string) s; for (int i = 0; i < t.Length; i++) { int c = char.ConvertToUtf32(t, i); if (c > 0xFFFF) i++; o.Add((double) c); } return o; }
    public static object fromCodepoints(object xs) { var sb = new StringBuilder(); foreach (var c in view(xs)) sb.Append(char.ConvertFromUtf32((int) num(c))); return sb.ToString(); }
    public static object blank(object c) { double d = num(c); return d == 32 || d == 9 || d == 10 || d == 13; }
    public static object number(object s) => double.TryParse(str(s).Trim(), NumberStyles.Float, Inv, out var d) ? d : double.NaN;

    /// <summary>a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise (`Expr.split(e, name)`)</summary>
    static bool core(object x) => x == null || x is List<object> || x is string || isNum(x) || x is bool || x is Many;
    public static object m_push(object xs, params object[] a) => core(xs) ? push(xs, a[0]) : call(xs, "push", a);
    public static object m_chars(object xs) => xs is string ? codepoints(xs) : get(xs, "chars");
    public static object m_pop(object xs) { if (core(xs)) { var l = L(xs); if (l.Count == 0) return null; var v = l[l.Count - 1]; l.RemoveAt(l.Count - 1); return v; } return get(xs, "pop"); }
    public static object m_map(object xs, params object[] a) { if (!core(xs)) return call(xs, "map", a); var w = each_of(xs); var o = new List<object>(w.Count); foreach (var x in w) o.Add(invoke(a[0], x)); return o; }
    public static object m_for(object xs, params object[] a) { if (!core(xs)) return call(xs, "for", a); foreach (var x in each_of(xs)) invoke(a[0], x); return null; }
    public static object m_some(object xs, params object[] a) { if (!core(xs)) return call(xs, "some", a); foreach (var x in each_of(xs)) if (truthy(invoke(a[0], x))) return true; return false; }
    public static object m_every(object xs, params object[] a) { if (!core(xs)) return call(xs, "every", a); foreach (var x in each_of(xs)) if (!truthy(invoke(a[0], x))) return false; return true; }
    public static object m_reduce(object xs, params object[] a) { if (!core(xs)) return call(xs, "reduce", a); object acc = a[0]; foreach (var x in each_of(xs)) acc = invoke(a[1], acc, x); return acc; }
    public static object m_starts_with(object xs, params object[] a) => core(xs) ? ((string) xs).StartsWith(str(a[0]), System.StringComparison.Ordinal) : call(xs, "starts_with", a);
    public static object m_ends_with(object xs, params object[] a) => core(xs) ? ((string) xs).EndsWith(str(a[0]), System.StringComparison.Ordinal) : call(xs, "ends_with", a);
    public static object m_replace(object xs, params object[] a) { if (!core(xs)) return call(xs, "replace", a); string f = str(a[0]); return f.Length == 0 ? xs : ((string) xs).Replace(f, str(a[1])); }
    public static object m_split(object xs, params object[] a)
    {
      if (!core(xs)) return call(xs, "split", a);
      string s = (string) xs, sep = str(a[0]); var o = new List<object>();
      if (sep.Length == 0) return codepointStrings(s);
      int at = 0; while (true) { int i = s.IndexOf(sep, at, System.StringComparison.Ordinal); if (i < 0) { o.Add(s.Substring(at)); return o; } o.Add(s.Substring(at, i - at)); at = i + sep.Length; }
    }
    public static object m_trim(object xs) => core(xs) ? ((string) xs).Trim() : get(xs, "trim");
    public static object m_upper(object xs) => core(xs) ? ((string) xs).ToUpperInvariant() : get(xs, "upper");
    public static object m_lower(object xs) => core(xs) ? ((string) xs).ToLowerInvariant() : get(xs, "lower");
    public static object m_lines(object xs) => core(xs) ? m_split(xs, "\n") : get(xs, "lines");
    public static object m_contains(object xs, params object[] a) => core(xs) ? contains(xs, a[0]) : call(xs, "contains", a);
    public static object m_index_of(object xs, params object[] a) => core(xs) ? indexOf(xs, a[0]) : call(xs, "index_of", a);
    public static object m_join(object xs, params object[] a) => core(xs) ? join(xs, a[0]) : call(xs, "join", a);
    public static object m_first(object xs) => core(xs) ? first(xs) : get(xs, "first");
    public static object m_last(object xs) => core(xs) ? last(xs) : get(xs, "last");
    public static object m_empty(object xs) => core(xs) ? num(len(xs)) == 0 : get(xs, "empty");
    public static object m_take(object xs, params object[] a) { if (!core(xs)) return call(xs, "take", a); int n = (int) num(a[0]); if (xs is string s) return s.Substring(0, System.Math.Max(0, System.Math.Min(n, s.Length))); var l = view(xs); return l.GetRange(0, System.Math.Max(0, System.Math.Min(n, l.Count))); }
    public static object m_drop(object xs, params object[] a) { if (!core(xs)) return call(xs, "drop", a); int n = (int) num(a[0]); if (xs is string s) return s.Substring(System.Math.Max(0, System.Math.Min(n, s.Length))); var l = view(xs); int f = System.Math.Max(0, System.Math.Min(n, l.Count)); return l.GetRange(f, l.Count - f); }
    public static object m_rest(object xs) => core(xs) ? m_drop(xs, 1.0) : get(xs, "rest");
    public static object m_concat(object xs, params object[] a) { if (!core(xs)) return call(xs, "concat", a); if (xs is string s) return s + str(a[0]); var o = items(xs); o.AddRange(view(a[0])); return o; }
    public static object m_reverse(object xs) { if (!core(xs)) return get(xs, "reverse"); if (xs is string s) { var c = s.ToCharArray(); System.Array.Reverse(c); return new string(c); } var o = items(xs); o.Reverse(); return o; }
    public static object m_sum(object xs) => core(xs) ? summed(xs) : get(xs, "sum");
    public static object m_most(object xs, params object[] a) => core(xs) ? most(xs, a[0]) : call(xs, "most", a);
    public static object m_sorted_by(object xs, params object[] a) => core(xs) ? sortedBy(xs, a[0]) : call(xs, "sorted_by", a);
    public static object m_each(object xs) => core(xs) ? new Many(items(xs)) : get(xs, "each");
    public static object m_sqrt(object x) => arith(x) ? System.Math.Sqrt(num(x)) : get(x, "sqrt");
    public static object m_floor(object x) => arith(x) ? System.Math.Floor(num(x)) : get(x, "floor");
    public static object m_abs(object x) => arith(x) ? System.Math.Abs(num(x)) : get(x, "abs");
    public static object m_magnitude(object x) => arith(x) ? System.Math.Abs(num(x)) : get(x, "magnitude");
    public static object m_cos(object x) => arith(x) ? System.Math.Cos(num(x)) : get(x, "cos");
    public static object m_sin(object x) => arith(x) ? System.Math.Sin(num(x)) : get(x, "sin");
    public static object m_round(object x) => arith(x) ? System.Math.Floor(num(x) + 0.5) : get(x, "round");
    public static object m_ln(object x) => arith(x) ? System.Math.Log(num(x)) : get(x, "ln");
    public static object m_exp(object x) => arith(x) ? System.Math.Exp(num(x)) : get(x, "exp");
    public static object m_atan2(object x, params object[] a) => arith(x) ? System.Math.Atan2(num(x), num(a[0])) : call(x, "atan2", a);
    public static object m_pow(object x, params object[] a) => arith(x) ? System.Math.Pow(num(x), num(a[0])) : call(x, "pow", a);

    // --- the Many: a superposition; members apply elementwise, equal things collapse ---------------------
    public static object many(object xs) => new Many(items(xs));
    public static object collapse(List<object> items)
    {
      if (items.Count == 0) return new Many(items);
      object f = items[0];
      foreach (var i in items) if (!(ReferenceEquals(i, f) || (i is List<object> && f is List<object> && eq(i, f)))) return new Many(items);
      return f;
    }
  }
}
